app.post('/api/payments',auth,async(q,s)=>{const client=await pool.connect();try{await client.query('BEGIN');const b=q.body||{},a=await client.query('SELECT * FROM students WHERE id=$1 FOR UPDATE',[b.student_id]);if(!a.rowCount)throw Error('Alumno no encontrado');const st=a.rows[0];let remaining=Number(b.amount);if(!(remaining>0))throw Error('El monto debe ser mayor a cero');const rec=await receipt();const r=await client.query('INSERT INTO payments(receipt_no,student_id,amount,method,concept,paid_at,period,notes,monthly_charge_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *',[rec,st.id,remaining,b.method||'Efectivo',b.concept||'Mensualidad',b.paid_at||today(),b.period||'',b.notes||'',b.charge_id||null]);if(String(b.concept||'').toLowerCase().includes('mensual')){const charges=await client.query(`SELECT mc.*,COALESCE((SELECT SUM(pa.amount) FROM payment_allocations pa WHERE pa.charge_id=mc.id),0) paid_amount FROM monthly_charges mc WHERE mc.student_id=$1 ORDER BY mc.period_start FOR UPDATE`,[st.id]);let ordered=charges.rows.filter(ch=>Number(ch.amount)-Number(ch.discount||0)-Number(ch.paid_amount||0)>0);if(b.charge_id){const chosen=ordered.find(ch=>String(ch.id)===String(b.charge_id));if(!chosen)throw Error('La mensualidad seleccionada no tiene saldo pendiente');ordered=[chosen,...ordered.filter(ch=>ch.id!==chosen.id)];}for(const ch of ordered){const bal=Math.max(0,Number(ch.amount)-Number(ch.discount||0)-Number(ch.paid_amount||0));if(bal<=0||remaining<=0)continue;const applied=Math.min(remaining,bal);await client.query('INSERT INTO payment_allocations(payment_id,charge_id,amount) VALUES($1,$2,$3)',[r.rows[0].id,ch.id,applied]);remaining-=applied;await client.query(`UPDATE monthly_charges SET balance=GREATEST(0,amount-discount-COALESCE((SELECT SUM(amount) FROM payment_allocations WHERE charge_id=$1),0)),status=CASE WHEN GREATEST(0,amount-discount-COALESCE((SELECT SUM(amount) FROM payment_allocations WHERE charge_id=$1),0))<=0 THEN 'Pagado' WHEN COALESCE((SELECT SUM(amount) FROM payment_allocations WHERE charge_id=$1),0)>0 THEN 'Parcial' ELSE 'Pendiente' END,updated_at=CURRENT_TIMESTAMP WHERE id=$1`,[ch.id]);}const latest=await client.query(`SELECT due_date FROM monthly_charges WHERE student_id=$1 AND balance>0 ORDER BY period_start LIMIT 1`,[st.id]);const due=latest.rows[0]?.due_date||null;await client.query('UPDATE students SET due_date=$1,updated_at=CURRENT_TIMESTAMP WHERE id=$2',[due,st.id]);}await audit(q.user,'CREATE','PAGOS',r.rows[0].id,'Recibo '+rec+(remaining>0?' · Saldo a favor '+remaining:''));await client.query('COMMIT');const full=await pool.query('SELECT p.*,s.matricula,s.name,s.last_name FROM payments p JOIN students s ON s.id=p.student_id WHERE p.id=$1',[r.rows[0].id]);s.status(201).json({...full.rows[0],unapplied_amount:remaining})}catch(e){await client.query('ROLLBACK');console.error(e);s.status(400).json({error:e.message||'No se pudo registrar el pago'})}finally{client.release()}});
