function mexicoNow(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const get=k=>parts.find(x=>x.type===k)?.value||'';return {date:`${get('year')}-${get('month')}-${get('day')}`,time:`${get('hour')}:${get('minute')}`}}
function studentAgeServer(birthDate){if(!birthDate)return null;const b=new Date(String(birthDate)+'T12:00:00');const n=new Date();if(Number.isNaN(b.getTime()))return null;let a=n.getFullYear()-b.getFullYear();const md=n.getMonth()-b.getMonth();if(md<0||(md===0&&n.getDate()<b.getDate()))a--;return a}
function isInfantilServer(student){const a=studentAgeServer(student?.birth_date);return a!==null&&a<12}
