app.post('/api/personal-attendance',auth,director,async(q,s)=>{try{const b=q.body||{},p=await pool.query('SELECT * FROM personal WHERE id=$1',[b.personal_id]);if(!p.rowCount)return s.status(404).json({error:'Personal no encontrado'});if(!b.entry_time||!b.exit_time)return s.status(400).json({error:'Registra entrada y salida'});const r=await pool.query('INSERT INTO personal_attendance(personal_id,attended_at,entry_time,exit_time,activity) VALUES($1,$2,$3,$4,$5) RETURNING *',[b.personal_id,b.attended_at||today(),b.entry_time,b.exit_time,b.activity||p.rows[0].area||p.rows[0].position]);await audit(q.user,'CREATE','ASISTENCIA_PERSONAL',r.rows[0].id,'Asistencia '+p.rows[0].matricula);s.status(201).json(r.rows[0])}catch(e){console.error(e);s.status(500).json({error:'No se pudo registrar la asistencia del personal'})}});
app.get('/api/payroll',auth,director,async(q,s)=>{try{const rows=[];const teachers=await pool.query(`SELECT t.id,t.name,t.last_name,t.rate_hour,COALESCE(SUM(CASE WHEN a.entry_time IS NOT NULL AND a.exit_time IS NOT NULL THEN EXTRACT(EPOCH FROM (('2000-01-01 '||a.exit_time)::timestamp-('2000-01-01 '||a.entry_time)::timestamp))/3600 ELSE 0 END),0) hours,COALESCE(SUM(CASE WHEN a.entry_time IS NOT NULL AND sch.start_time IS NOT NULL AND EXTRACT(EPOCH FROM (('2000-01-01 '||a.entry_time)::timestamp-('2000-01-01 '||sch.start_time)::timestamp))/60>10 THEN EXTRACT(EPOCH FROM (('2000-01-01 '||a.entry_time)::timestamp-('2000-01-01 '||sch.start_time)::timestamp))/60-10 ELSE 0 END),0) late_minutes FROM teachers t LEFT JOIN teacher_attendance a ON a.teacher_id=t.id AND a.attended_at>=date_trunc('month',CURRENT_DATE)::date::text LEFT JOIN LATERAL (SELECT sc.start_time FROM schedules sc WHERE sc.teacher_id=t.id AND sc.active=1 AND sc.day_of_week=(EXTRACT(ISODOW FROM a.attended_at::date)) AND sc.start_time<=a.entry_time ORDER BY sc.start_time DESC LIMIT 1) sch ON true GROUP BY t.id`);teachers.rows.forEach(x=>{const hours=Number(x.hours||0),late=Number(x.late_minutes||0),discount=late/60*Number(x.rate_hour||0),gross=hours*Number(x.rate_hour||0);rows.push({type:'Maestro',name:x.name,last_name:x.last_name,hours,late_minutes:late,retardo_minutes:late,discount,subtotal:gross,total:Math.max(0,gross-discount)})});const people=await pool.query("SELECT p.id,p.name,p.last_name,p.rate_hour,COALESCE(SUM(CASE WHEN a.entry_time IS NOT NULL AND a.exit_time IS NOT NULL THEN EXTRACT(EPOCH FROM (('2000-01-01 '||a.exit_time)::timestamp-('2000-01-01 '||a.entry_time)::timestamp))/3600 ELSE 0 END),0) hours FROM personal p LEFT JOIN personal_attendance a ON a.personal_id=p.id AND a.attended_at>=date_trunc('month',CURRENT_DATE)::date::text GROUP BY p.id");people.rows.forEach(x=>{const hours=Number(x.hours||0),gross=hours*Number(x.rate_hour||0);rows.push({type:'Personal',name:x.name,last_name:x.last_name,hours,late_minutes:0,retardo_minutes:0,discount:0,subtotal:gross,total:gross})});s.json(rows)}catch(e){console.error(e);s.status(500).json({error:'No se pudo calcular la nómina'})}});
