app.post('/api/attendance/scan',auth,async(q,s)=>{try{const b=q.body||{},code=String(b.code||'').trim();if(!code)return s.status(400).json({error:'Escanea una matrícula o QR'});const mat=code.includes('|')?code.split('|').pop():code;const r=await pool.query(`SELECT s.*,d.name discipline_name FROM students s LEFT JOIN disciplines d ON d.id=s.discipline_id WHERE s.matricula=$1 LIMIT 1`,[mat]);if(!r.rowCount)return s.status(404).json({error:'Alumno no encontrado'});const st=r.rows[0];if(st.status!=='Activo')return s.json({allowed:false,reason:'Alumno dado de baja',student:{id:st.id,matricula:st.matricula,name:st.name,last_name:st.last_name,status:st.status,due_date:st.due_date,photo_data:st.photo_data||''},schedule:null});const charges=await ensureMonthlyCharges(st.id,12);const open=charges.filter(c=>Number(c.balance)>0);const current=open[0];const c=await getConfig(),tol=Number(c.tolerance_days||0),due=current?.due_date||st.due_date;let allowed=true;if(due){const limit=new Date(due+'T12:00:00');limit.setDate(limit.getDate()+tol);allowed=limit>=new Date();}const infantil=isInfantilServer(st);const schedule=allowed&&infantil?await scheduleForStudent(st.id,today(),new Date().toTimeString().slice(0,5)):null;if(!allowed)return s.json({allowed:false,reason:'Mensualidad vencida',student:{id:st.id,matricula:st.matricula,name:st.name,last_name:st.last_name,status:st.status,due_date:due,photo_data:st.photo_data||''},schedule,charge:current||null});const discipline=infantil?(schedule?.discipline_name||st.discipline_name||''):'';const ar=await pool.query('INSERT INTO attendance(student_id,attended_at,discipline,group_name,status,notes,device_id,access_result) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[st.id,today(),discipline,'','Presente',b.notes||'',b.device_id||null,'Permitido']);await audit(q.user,'CREATE','ASISTENCIA',ar.rows[0].id,'Escaneo QR '+st.matricula);s.json({allowed:true,reason:'Acceso permitido',student:{id:st.id,matricula:st.matricula,name:st.name,last_name:st.last_name,status:st.status,due_date:due,photo_data:st.photo_data||''},attendance:ar.rows[0],schedule,charge:current||null})}catch(e){console.error(e);s.status(500).json({error:'No se pudo procesar el QR'})}});
app.get('/api/report',auth,async(q,s)=>{try{const [a,b,c,d]=await Promise.all([pool.query('SELECT COUNT(*) n FROM students'),pool.query("SELECT COUNT(*) n FROM students WHERE status='Activo'"),pool.query("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE paid_at >= date_trunc('month',CURRENT_DATE)::date::text"),pool.query("SELECT COUNT(*) n FROM students WHERE status='Activo' AND due_date < CURRENT_DATE::text")]);s.json({alumnos:+a.rows[0].n,activos:+b.rows[0].n,ingresos:+c.rows[0].n,vencidos:+d.rows[0].n})}catch(e){console.error(e);s.status(500).json({error:'No se pudo generar el reporte'})}});
app.delete('/api/audit/:id',auth,director,async(q,s)=>{try{const r=await pool.query('DELETE FROM audit WHERE id=$1 RETURNING id',[q.params.id]);if(!r.rowCount)return s.status(404).json({error:'Registro de bitácora no encontrado'});s.json({ok:true})}catch(e){s.status(500).json({error:'No se pudo eliminar el registro de bitácora'})}});
app.delete('/api/trash/:id/permanent',auth,director,async(q,s)=>{try{const r=await pool.query('DELETE FROM trash WHERE id=$1 RETURNING id,entity_type,name',[q.params.id]);if(!r.rowCount)return s.status(404).json({error:'Registro de papelera no encontrado'});await audit(q.user,'PURGE','PAPELERA',Number(q.params.id),'Eliminación permanente: '+(r.rows[0].entity_type||'registro'));s.json({ok:true})}catch(e){s.status(500).json({error:'No se pudo eliminar permanentemente'})}});

app.get('*',(q,s)=>s.sendFile(path.join(__dirname,'index.html')));

init().then(()=>app.listen(PORT,'0.0.0.0',()=>console.log(`EmpoderArte V2.5 en puerto ${PORT}`))).catch(e=>{console.error('No se pudo iniciar la base de datos',e);process.exit(1)});
process.on('SIGTERM',async()=>{await pool.end();process.exit(0)});
